import random
import struct

# Structured arbitrary binary buffer generator with strict bounds checks.
# Produces TLV-composed segments that resemble NCNN param/model/pixel buffers.

MAGIC_PARAM_BIN = b"\x00\x00\r\xed"
MAGIC_MODEL_BIN = b"\x00\x00\xca\xfe"


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(max(0, n)))


def _c_string(r: random.Random, minlen: int = 0, maxlen: int = 64) -> bytes:
    if maxlen < minlen:
        maxlen = minlen
    n = r.randint(minlen, maxlen)
    s = bytearray()
    alphabet = b"_-.:/\\" + bytes(range(48, 58)) + bytes(range(65, 91)) + bytes(range(97, 123))
    for _ in range(n):
        s.append(alphabet[r.randrange(len(alphabet))])
    s.append(0)
    return bytes(s)


def _make_param_bin_like(r: random.Random, max_size: int) -> bytes:
    max_size = max(0, max_size)
    if max_size == 0:
        return b""
    if max_size <= 8:
        return _rand_bytes(r, max_size)
    out = bytearray()
    out += MAGIC_PARAM_BIN
    out += struct.pack('<III', r.randrange(1, 5), r.randrange(1, 32), r.randrange(1, 64))
    n_entries = r.randint(2, 12)
    for _ in range(n_entries):
        if len(out) > max_size - 16:
            break
        pid = r.randrange(0, 65536)
        ptype = r.randrange(0, 4)  # 0=int,1=float,2=mat,3=string
        if ptype == 0:
            payload = struct.pack('<i', r.randint(-10000, 10000))
        elif ptype == 1:
            payload = struct.pack('<f', r.uniform(-10.0, 10.0))
        elif ptype == 2:
            dims = r.randint(1, 4)
            shape = [1, 1, 1]
            if dims >= 1:
                shape[0] = r.randint(1, 16)
            if dims >= 2:
                shape[1] = r.randint(1, 16)
            if dims >= 3:
                shape[2] = r.randint(1, 8)
            elemsize = r.choice([1, 2, 4])
            elempack = r.choice([1, 4, 8]) if elemsize in (2, 4) else 1
            total = shape[0] * shape[1] * shape[2] * elempack
            total = min(total, 128)
            payload = bytearray()
            payload += struct.pack('<I', dims)
            payload += struct.pack('<III', shape[0], shape[1], shape[2])
            payload += struct.pack('<II', elemsize, elempack)
            # ensure space
            remaining = max_size - len(out) - 12 - len(payload)
            data_bytes = max(0, min(remaining, total * elemsize))
            payload += _rand_bytes(r, data_bytes)
            payload = bytes(payload)
        else:
            s = _c_string(r, 0, 32)
            payload = s
        # write entry if space permits
        remaining = max_size - len(out)
        entry_len = 12 + len(payload)
        if entry_len > remaining:
            break
        out += struct.pack('<III', pid, ptype, len(payload))
        out += payload
    return bytes(out[:max_size])


def _make_model_bin_like(r: random.Random, max_size: int) -> bytes:
    max_size = max(0, max_size)
    if max_size == 0:
        return b""
    if max_size <= 8:
        return _rand_bytes(r, max_size)
    out = bytearray()
    out += MAGIC_MODEL_BIN
    out += struct.pack('<I', r.randrange(1, 4))
    n_arrays = r.randint(2, 16)
    for _ in range(n_arrays):
        if len(out) > max_size - 16:
            break
        etype = r.choice([1, 2, 3])  # 1=float32 2=float16 3=int8
        # compute max elements we can fit
        per = 4 if etype == 1 else (2 if etype == 2 else 1)
        remaining_bytes = max_size - len(out) - 8  # for header etype+len
        if remaining_bytes <= 0:
            break
        max_len = remaining_bytes // per
        if max_len <= 0:
            break
        low = 1  # allow small arrays when tight
        high = min(256, max_len)
        if high < low:
            break
        length = r.randint(low, high)
        out += struct.pack('<II', etype, length)
        if etype == 1:
            for _i in range(length):
                out += struct.pack('<f', r.uniform(-3.0, 3.0))
        elif etype == 2:
            for _i in range(length):
                out += struct.pack('<H', r.randrange(0, 65536))
        else:
            out += _rand_bytes(r, length)
    return bytes(out[:max_size])


def _make_pixel_block(r: random.Random, max_size: int) -> bytes:
    max_size = max(0, max_size)
    if max_size == 0:
        return b""
    if max_size <= 1:
        return _rand_bytes(r, max_size)
    w = r.randint(8, 64)
    h = r.randint(8, 64)
    fmt = r.choice([3, 1, 2, 4, 5])  # GRAY, RGB, BGR, RGBA, BGRA
    ch = {3: 1, 1: 3, 2: 3, 4: 4, 5: 4}[fmt]
    stride = w * ch
    total_needed = h * stride
    total = max(1, min(max_size, total_needed))
    buf = bytearray()
    for y in range(h):
        for x in range(w):
            base = (x * 7 + y * 13) & 0xFF
            for c in range(ch):
                buf.append((base + c * 17) & 0xFF)
                if len(buf) >= total:
                    return bytes(buf[:max_size])
    return bytes(buf[:max_size])


def _safe_randint(r: random.Random, a: int, b: int) -> int:
    if b < a:
        return a
    return r.randint(a, b)


def _compose_segments(r: random.Random, max_total: int) -> bytes:
    max_total = max(0, max_total)
    if max_total == 0:
        return b""
    out = bytearray()
    if max_total <= 8:
        return _rand_bytes(r, max_total)
    # Optional name prefix
    if r.random() < 0.4:
        s = _c_string(r, 3, 24)
        header = b"NAME\x00" + struct.pack('<I', len(s)) + s
        if len(header) < max_total:
            out += header
    # Add 2-4 segments
    nseg = _safe_randint(r, 2, 4)
    for _ in range(nseg):
        if len(out) > max_total - 12:
            break
        remaining = max_total - len(out) - 8  # space for tag+len
        if remaining <= 0:
            break
        choice = r.random()
        if choice < 0.33:
            upper = min(1024, remaining)
            seg_max = _safe_randint(r, 16, max(16, upper))
            seg = _make_param_bin_like(r, seg_max)
            tag = b"PARM"
        elif choice < 0.66:
            upper = min(2048, remaining)
            seg_max = _safe_randint(r, 16, max(16, upper))
            seg = _make_model_bin_like(r, seg_max)
            tag = b"WEIG"
        else:
            upper = min(1024, remaining)
            seg_max = _safe_randint(r, 16, max(16, upper))
            seg = _make_pixel_block(r, seg_max)
            tag = b"PXLS"
        if not seg:
            seg = _rand_bytes(r, min(remaining, 16))
        seg = seg[:remaining]
        out += tag + struct.pack('<I', len(seg)) + seg
    return bytes(out[:max_total])


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    max_size = 4096
    size_choice = r.random()
    if size_choice < 0.2:
        target = _safe_randint(r, 16, 128)
    elif size_choice < 0.7:
        target = _safe_randint(r, 128, 2048)
    else:
        target = _safe_randint(r, 256, max_size)

    buf = bytearray(_compose_segments(r, target))

    if not buf:
        buf = bytearray(_rand_bytes(r, _safe_randint(r, 1, max(1, target))))
    if r.random() < 0.3 and len(buf) + 8 <= target:
        trailer = b"TRLR" + struct.pack('<I', r.randrange(0, 1 << 31))
        buf += trailer

    return bytes(buf[:max_size])
